import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2018-Jun-21 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Jun-21 :: Ceph Performance Weekly","date":"2018-06-21T00:00:00.000Z","updated":"2018-06-22T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","RBD","Blue Store","PG日志","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Jun-21_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Jun-21_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2018/2018-Jun-21_-_-_Ceph_Performance_Weekly.md"};function s(n,l,a,p,u,_){return i(),r("div",null,[...l[0]||(l[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年6月21日</p><p><strong>参会人员</strong>： [请列出参会人员姓名]</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储系统中的关键技术优化，包括RBD、Blue Store、PG日志等。</p><p><strong>关键细节</strong>：</p><ul><li><strong>RBD优化</strong>： <ul><li>讨论了RBD在磁盘上的性能表现，并对比了不同硬件配置下的性能差异。</li><li>讨论了PG日志对性能的影响，并提出了优化方案，例如将PG日志存储在更快的存储设备上。</li></ul></li><li><strong>Blue Store优化</strong>： <ul><li>讨论了Blue Store缓存大小对OSD内存使用的影响，并提出了自动调整缓存大小的方案。</li><li>讨论了如何设置缓存大小优先级，并确保缓存大小与OSD内存目标一致。</li><li>讨论了如何处理内存压力下的缓存调整，并提出了使用RSS内存作为目标的方法。</li></ul></li><li><strong>PG日志优化</strong>： <ul><li>讨论了PG日志对性能的影响，并提出了优化方案，例如将PG日志存储在更快的存储设备上。</li><li>讨论了不同类型数据在RocksDB中的存储方式，并提出了针对不同数据类型设置不同压缩策略的方案。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何优化RBD在磁盘上的性能表现。</li><li>如何优化Blue Store缓存大小对OSD内存使用的影响。</li><li>如何优化PG日志对性能的影响。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>将PG日志存储在更快的存储设备上，例如NVM Express (NVMe)。</li><li>开发自动调整Blue Store缓存大小的方案。</li><li>研究针对不同数据类型设置不同压缩策略的方案。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>进行更多测试，以验证优化方案的可行性。</li><li>开发自动调整Blue Store缓存大小的代码。</li><li>与RocksDB团队合作，讨论针对不同数据类型设置不同压缩策略的方案。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph性能计数器的优化。</li><li>讨论了Ceph OpTracker的优化。</li><li>讨论了Ceph的存储目标优化。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文原文的关键词，例如： <ul><li>RBD (Rados Block Device)</li><li>Blue Store</li><li>PG日志</li><li>RocksDB</li><li>NVM Express (NVMe)</li><li>OpTracker</li><li>性能计数器</li></ul></li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了Ceph分布式存储系统中的关键技术优化，并提出了相应的解决方案。这些优化方案将有助于提高Ceph的性能和可靠性。</p>',19)])])}const h=e(o,[["render",s]]);export{g as __pageData,h as default};
